function httpBinary3(url, range) {
  var headers = { "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X)", "Referer": "https://www.missevan.com/" };
  if (range) headers["Range"] = range;
  var input = { url: url, method: "GET", headers: headers, base64Data: true, timeout: 25 };
  return (typeof Widget.http.request === "function" ? Widget.http.request(input) : Widget.callAsync("request", input));
}

async function httpJson3(url) {
  var resp = await httpBinary3(url);
  var text = new TextDecoder("utf-8").decode(b64ToBytes(resp.data));
  return JSON.parse(text);
}

async function httpText3(url) {
  var resp = await httpBinary3(url);
  return new TextDecoder("utf-8").decode(b64ToBytes(resp.data));
}

/** 分块下载整个文件 */
async function downloadAll(url, total) {
  var CHUNK = 768 * 1024;
  var out = new Uint8Array(total);
  var off = 0;
  var t0 = Date.now();
  while (off < total) {
    var end = off + CHUNK - 1;
    if (end >= total) end = total - 1;
    var resp = await httpBinary3(url, "bytes=" + off + "-" + end);
    var piece = b64ToBytes(resp.data);
    if (piece.length === 0) break;
    out.set(piece, off);
    off += piece.length;
  }
  console.log("[dec] 下载", off, "字节 /", Date.now() - t0, "ms");
  return out;
}

